    /// Extracts the first grapheme cluster of the string.
    /// Fails with an error if the string is empty.
    ///
    /// If a `pattern` is given, returns the first grapheme cluster whose
    /// first codepoint belongs to that character class instead. Fails with an
    /// error if there is no such cluster. If a `case` is given, the extracted
    /// grapheme cluster is converted to that case.
    #[func]
    pub fn first(
        &self,
        /// A character class that the extracted grapheme cluster must match.
        /// One of `{"alpha"}`, `{"numeric"}`, `{"alphanumeric"}`,
        /// `{"uppercase"}`, `{"lowercase"}` or `{"whitespace"}`.
        #[named]
        pattern: Option<Str>,
        /// The case to convert the extracted grapheme cluster to. One of
        /// `{"upper"}`, `{"lower"}` or `{"title"}`.
        #[named]
        case: Option<Str>,
    ) -> StrResult<Str> {
        let cluster = self.pick_cluster(false, pattern.as_deref())?;
        convert_case(cluster, case.as_deref())
    }

    /// Extracts the last grapheme cluster of the string.
